css:
.button {
  height: 4em;
  width: 12em;
  border-radius: 18px;
  border: 4px solid lightskyblue;
  padding: 0.2em;
  overflow: hidden;
}

.text {
  display: block;
  font-size: 20px;
  color: lightskyblue;
}

.afterText {
  display: none;
}

.clouds {
  display: none;
  height: 4rem;
  width: 8rem;
}

.button:hover {
  cursor: pointer;
}

.button:hover .text {
  text-decoration: underline;
  font-weight: bold;
}

.button:focus {
  transition: ease-in 200ms;
  background-color: lightskyblue;
  border: none;
}

.button:focus .text {
  display: none;
}

.button:focus .afterText {
  animation: hoverMovement 1s ease-in alternate infinite;
  display: block;
  font-size: 25px;
  letter-spacing: 5px;
  color: rgb(90, 94, 97);
}

.button:focus .clouds {
  display: block;
  animation: cloudMovement ease-in-out 3s infinite;
  margin-top: -1.5em;
}

@keyframes hoverMovement {
  from {
    transform: translateY(0em);
  }

  to {
    transform: translateY(-0.1em);
  }
}

@keyframes cloudMovement {
  from {
    transform: translateX(-5em);
  }

  to {
    transform: translateX(10em);
  }
}
